b <- 1:10
resu <- matrix(NA,nrow=5,ncol=10)
for (i in 1:5)
{
   for (j in 1:5)
    {
    resu[i,j]=a[i]+b[j]  # will be more complicated
    }
}
# Do I have to create a list like this i order to use sapply?
data=list()
for (i in 1:5)
{
 for (j in 1:5)
 {
  data[[(i-1)*5+j]]=list(a=a[i],b=b[j])
 }
}

Thank you for your attention.
Best wishes,
Jie

